class Solution {
public:
    vector<long long> minimumRelativeLosses(vector<int>& prices, vector<vector<int>>& queries) {
        int n = prices.size();
        sort(prices.begin(), prices.end());
        vector<long long> s(n + 1, 0);
        for (int i = 0; i < n; ++i) s[i + 1] = s[i] + prices[i];
        auto f = [&](int k, int m) {
            int l = 0, r = upper_bound(prices.begin(), prices.end(), k) - prices.begin();
            r = min(r, m);
            while (l < r) {
                int mid = (l + r) >> 1;
                int right = m - mid;
                if (prices[mid] < 2LL * k - prices[n - right]) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            return l;
        };
        vector<long long> ans;
        for (auto& q : queries) {
            int k = q[0], m = q[1];
            int l = f(k, m);
            int r = m - l;
            ans.push_back(s[l] + 2LL * k * r - (s[n] - s[n - r]));
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    private int n;
    private int[] prices;

    public long[] minimumRelativeLosses(int[] prices, int[][] queries) {
        n = prices.length;
        Arrays.sort(prices);
        this.prices = prices;
        long[] s = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            s[i + 1] = s[i] + prices[i];
        }
        int q = queries.length;
        long[] ans = new long[q];
        for (int i = 0; i < q; ++i) {
            int k = queries[i][0], m = queries[i][1];
            int l = f(k, m);
            int r = m - l;
            ans[i] = s[l] + 2L * k * r - (s[n] - s[n - r]);
        }
        return ans;
    }

    private int f(int k, int m) {
        int l = 0, r = Arrays.binarySearch(prices, k);
        if (r < 0) {
            r = -(r + 1);
        } else {
            while (r < n && prices[r] == k) r++;
        }
        r = Math.min(m, r);
        while (l < r) {
            int mid = (l + r) >> 1;
            int right = m - mid;
            if (prices[mid] < 2L * k - prices[n - right]) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

/**
 * @param {number[]} prices
 * @param {number[][]} queries
 * @return {number[]}
 */
var minimumRelativeLosses = function(prices, queries) {
    const n = prices.length;
    prices.sort((a, b) => a - b);
    const s = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) {
        s[i + 1] = s[i] + BigInt(prices[i]);
    }
    function bisectRight(arr, val) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = Math.floor((l + r) / 2);
            if (arr[m] <= val) l = m + 1;
            else r = m;
        }
        return l;
    }
    function f(k, m) {
        let l = 0, r = Math.min(m, bisectRight(prices, k));
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            const right = m - mid;
            if (BigInt(prices[mid]) < 2n * BigInt(k) - BigInt(prices[n - right])) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
    const ans = [];
    for (const [k, m] of queries) {
        const l = f(k, m);
        const r = m - l;
        const loss = s[l] + 2n * BigInt(k) * BigInt(r) - (s[n] - s[n - r]);
        ans.push(Number(loss));
    }
    return ans;
};
